package api

import (
	"errors"
	"math"
	"net/http"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/KyAnhVo/brainlog-website/server/internal/ids"
	"github.com/KyAnhVo/brainlog-website/server/internal/model"
	"github.com/KyAnhVo/brainlog-website/server/internal/store"
)

// TrackingBase minus trackingNumber (generated by the server). customerId is not accepted
// (no customer entity exists yet), and unknown fields are rejected by decodeJSON.
type trackingCreateRequest struct {
	Cont            *string                `json:"cont"`
	Seal            *string                `json:"seal"`
	POL             string                 `json:"pol"`
	POD             string                 `json:"pod"`
	PhysicalDetails *physicalDetailsCreate `json:"physicalDetails"`
}

// Pointers distinguish "missing" from 0, so a missing required number is a 400, not a silent 0.
type physicalDetailsCreate struct {
	PcsCount   *int              `json:"pcsCount"`
	WeightKg   *float64          `json:"weightKg"`
	Dimensions *dimensionsCreate `json:"dimensions"`
}

type dimensionsCreate struct {
	LengthCm *float64 `json:"lengthCm"`
	WidthCm  *float64 `json:"widthCm"`
	HeightCm *float64 `json:"heightCm"`
}

const (
	maxPortLen     = 200
	maxContSealLen = 100
	maxMeasure     = 1e9 // sanity bound for kg and cm
	maxPcsCount    = 1_000_000_000
	// 40-bit random numbers essentially never collide; this only guards against a fluke.
	trackingNumberAttempts = 5
)

func positiveMeasure(v *float64) bool {
	return v != nil && *v > 0 && *v <= maxMeasure && !math.IsInf(*v, 0) && !math.IsNaN(*v)
}

// validateTrackingCreate returns the tracking to store (number, creator and times are
// filled in by the caller), or a client-facing error message.
func validateTrackingCreate(req trackingCreateRequest) (model.Tracking, string) {
	var t model.Tracking

	optional := func(p *string, field string) (string, string) {
		if p == nil {
			return "", ""
		}
		v := strings.TrimSpace(*p)
		if utf8.RuneCountInString(v) > maxContSealLen {
			return "", field + " is too long"
		}
		return v, "" // empty after trimming means absent
	}
	var msg string
	if t.Cont, msg = optional(req.Cont, "cont"); msg != "" {
		return t, msg
	}
	if t.Seal, msg = optional(req.Seal, "seal"); msg != "" {
		return t, msg
	}

	t.POL = strings.TrimSpace(req.POL)
	t.POD = strings.TrimSpace(req.POD)
	switch {
	case t.POL == "":
		return t, "pol must not be empty"
	case t.POD == "":
		return t, "pod must not be empty"
	case utf8.RuneCountInString(t.POL) > maxPortLen:
		return t, "pol is too long"
	case utf8.RuneCountInString(t.POD) > maxPortLen:
		return t, "pod is too long"
	}

	if p := req.PhysicalDetails; p != nil {
		if !positiveMeasure(p.WeightKg) {
			return t, "physicalDetails.weightKg must be a positive number"
		}
		d := p.Dimensions
		if d == nil || !positiveMeasure(d.LengthCm) || !positiveMeasure(d.WidthCm) || !positiveMeasure(d.HeightCm) {
			return t, "physicalDetails.dimensions needs positive lengthCm, widthCm and heightCm"
		}
		if p.PcsCount != nil && (*p.PcsCount < 1 || *p.PcsCount > maxPcsCount) {
			return t, "physicalDetails.pcsCount must be a positive integer"
		}
		t.Physical = &model.PhysicalDetails{
			PcsCount:   p.PcsCount,
			WeightKg:   *p.WeightKg,
			Dimensions: model.Dimensions{LengthCm: *d.LengthCm, WidthCm: *d.WidthCm, HeightCm: *d.HeightCm},
		}
	}
	return t, ""
}

// trackingCreatedStatus is the status every new tracking starts with.
func trackingCreatedStatus(t model.Tracking, now time.Time) model.Status {
	return model.Status{
		ID:            ids.NewUUIDv7(now),
		Type:          model.StatusGood,
		Status:        model.StatusTrackingCreated,
		Warnings:      []string{},
		OccurringTime: now,
		Location:      t.POL,
		CreatorID:     t.CreatorID,
		CreationTime:  now,
	}
}

// POST /api/admin/tracking (any logged-in role). Responds like GET /api/admin/tracking/{n}.
func (s *Server) handleCreateTracking(w http.ResponseWriter, r *http.Request) {
	var req trackingCreateRequest
	if err := decodeJSON(w, r, &req); err != nil {
		writeDecodeError(w, err)
		return
	}
	t, msg := validateTrackingCreate(req)
	if msg != "" {
		writeError(w, http.StatusBadRequest, msg)
		return
	}
	now := s.now()
	t.CreatorID = currentAccount(r.Context()).ID
	t.CreationTime = now
	first := trackingCreatedStatus(t, now)

	for attempt := 1; ; attempt++ {
		t.TrackingNumber = ids.NewTrackingNumber()
		err := s.store.CreateTracking(r.Context(), t, first)
		if err == nil {
			break
		}
		if !errors.Is(err, store.ErrConflict) || attempt == trackingNumberAttempts {
			s.internalError(w, r, err)
			return
		}
	}

	writeJSON(w, http.StatusOK, adminTrackingResponse{
		Details:  toTrackingDetails(t),
		Statuses: []statusDTO{toStatus(first)},
	})
}
